-- Cookies become the main line: add the NY cookie category and products, hide the earlier lines.
on conflict (id) do nothing;

on conflict (slug) do nothing;

update public.products set active = false, bestseller = false
 where category in ('cakes', 'mini-cakes', 'cupcakes', 'treats', 'seasonal');

update public.settings
   set value = jsonb_set(value, '{announcement}', to_jsonb('Order a day ahead for fresh-baked cookies'::text))
 where key = 'business' and value->>'announcement' = 'Order 48 hours ahead for celebration cakes';
